INSERT INTO site_pages (page_name, content_json) VALUES ('global', '{"nav":{"logo_image":"/assets/img/catering-menu-logo.png","logo_icon":"fas fa-utensils","logo_text":"Catering Menu","links":[{"label":"Home","url":"/index.html"},{"label":"Restaurants","url":"/listings.html"},{"label":"About Us","url":"/about.html"},{"label":"FAQs","url":"/faqs.html"},{"label":"Contact","url":"/contact.html"}],"cta_btn":{"label":"Get Listed","url":"/get-listed.html"}},"footer":{"about_heading":"About Catering Menu","about_text":"Catering Menu is the premier destination for discovering exceptional dining and catering experiences. We connect food lovers with the finest restaurants, curated reviews, and unforgettable culinary journeys across the city.","quick_heading":"Quick Links","quick_links":[{"label":"Home","url":"/index.html"},{"label":"About Us","url":"/about.html"},{"label":"Restaurants","url":"/listings.html"},{"label":"Get Listed","url":"/get-listed.html"},{"label":"FAQs","url":"/faqs.html"},{"label":"Contact","url":"/contact.html"}],"legal_heading":"Legal","legal_links":[{"label":"Privacy Policy","url":"/privacy.html"},{"label":"Terms of Service","url":"/terms.html"},{"label":"Disclaimer","url":"/disclaimer.html"}],"social_heading":"Follow Us","socials":[{"icon":"fab fa-facebook-f","url":"#","label":"Facebook"},{"icon":"fab fa-twitter","url":"#","label":"Twitter"},{"icon":"fab fa-instagram","url":"#","label":"Instagram"},{"icon":"fab fa-youtube","url":"#","label":"YouTube"}],"copyright":"\u00a9 2026 Catering Menu. All rights reserved."}}');
INSERT INTO site_pages (page_name, content_json) VALUES ('home', '{"hero":{"badge":"Premium Dining Directory","title":"Discover Extraordinary Dining Experiences","subtitle":"Explore handpicked restaurants, read authentic reviews, and find your next favorite meal \u2014 all in one place.","search_placeholder":"Search restaurants by name or cuisine...","search_btn":{"label":"Explore Now","url":"#restaurants"},"stats":[{"number":"2,500+","label":"Restaurants"},{"number":"15,000+","label":"Reviews"},{"number":"50,000+","label":"Happy Diners"}]},"how_it_works":{"overline":"Simple Process","title":"How DineVault Works","subtitle":"Finding the perfect restaurant is just three simple steps away.","steps":[{"icon":"fas fa-search","title":"Browse & Discover","text":"Explore our curated collection of top-rated restaurants. Filter by cuisine, location, or rating to find exactly what you crave."},{"icon":"fas fa-star","title":"Read Real Reviews","text":"Dive into authentic reviews from verified diners. See ratings, photos, and detailed experiences before making your choice."},{"icon":"fas fa-book-open","title":"Reserve & Enjoy","text":"Connect directly with your chosen restaurant. Get directions, view menus, and plan your perfect dining experience."}]},"featured":{"overline":"Our Selection","title":"Featured Restaurants","subtitle":"Handpicked dining destinations that our community loves the most.","view_all_btn":{"label":"View All Restaurants","url":"\/restaurant-business\/restaurant.php?id=1"}},"split_1":{"overline":"Why Choose Us","title":"Curated by Experts, Loved by Diners","text":"Every restaurant on DineVault is handpicked by our culinary experts. We visit, taste, and verify each establishment before it appears on our platform. Our rigorous selection process ensures that when you choose a restaurant from DineVault, you are choosing excellence.","bullets":[{"icon":"fas fa-check-circle","text":"Expert-curated restaurant selections"},{"icon":"fas fa-check-circle","text":"Authentic verified customer reviews"},{"icon":"fas fa-check-circle","text":"Real-time menu and pricing updates"},{"icon":"fas fa-check-circle","text":"Exclusive partnership perks and offers"}],"image_url":"https:\/\/images.unsplash.com\/photo-1600891964092-4316c288032e?w=800","image_alt":"Premium steak dining experience","btn":{"label":"Learn More","url":"\/restaurant-business\/about.php"}},"split_2":{"overline":"Community Driven","title":"Real Reviews from Real Food Lovers","text":"Our community of over 50,000 passionate diners shares their honest experiences every day. From hidden neighborhood gems to celebrated fine dining destinations, our reviews help you make confident choices. Every review is verified, every rating is genuine, and every recommendation comes from someone who has truly dined there.","bullets":[{"icon":"fas fa-shield-alt","text":"100% verified diner reviews"},{"icon":"fas fa-users","text":"50,000+ active community members"},{"icon":"fas fa-camera","text":"Photo reviews and food stories"},{"icon":"fas fa-trophy","text":"Top reviewer recognition program"}],"image_url":"https:\/\/images.unsplash.com\/photo-1551218808-94e220e084d2?w=800","image_alt":"Friends enjoying dinner together","btn":{"label":"Read Reviews","url":"\/restaurant-business\/restaurant.php?id=1"}},"cta":{"title":"Own a Restaurant?","text":"Join DineVault and reach thousands of food enthusiasts. List your restaurant for free and let diners discover your culinary excellence.","btn":{"label":"Get Listed Today","url":"\/restaurant-business\/get-listed.php"}}}');
INSERT INTO site_pages (page_name, content_json) VALUES ('about', '{"hero":{"title":"About DineVault","subtitle":"We are passionate about connecting people with unforgettable dining experiences."},"mission":{"title":"Our Mission","text":"To empower every food lover with the tools, insights, and community they need to discover restaurants that truly delight. We believe every meal should be an experience worth remembering, and our platform is designed to make finding that perfect spot effortless and enjoyable."},"vision":{"title":"Our Vision","text":"To become the world''s most trusted and comprehensive restaurant discovery platform, where authenticity, quality, and community come together to redefine how people explore food. We envision a future where no great restaurant goes unnoticed and no diner settles for less."},"stats":[{"number":"2,500+","label":"Restaurants Listed"},{"number":"15,000+","label":"Reviews Submitted"},{"number":"50,000+","label":"Happy Diners"},{"number":"120+","label":"Cities Covered"}],"cta":{"title":"Own a Restaurant?","text":"Join DineVault and reach thousands of food enthusiasts.","btn":{"label":"Get Listed Today","url":"\/restaurant-business\/get-listed.php"}}}');
