INSERT INTO site_pages (page_name, content_json) VALUES ('get-listed', '{"hero":{"title":"List Your Restaurant","subtitle":"Join thousands of restaurants already on DineVault. Showcase your menu, gather reviews, and attract new customers."},"form":{"title":"Submit Your Restaurant","name_label":"Restaurant Name","banner_label":"Banner Image URL","about_label":"About Your Restaurant","menu_label":"Direct Menu Text","days_label":"Opening Days & Hours","locations_label":"Location(s)","submit_btn":{"label":"Submit for Review","url":"#"},"success_msg":"Thank you! Your restaurant has been submitted for review. Our team will approve it shortly."}}');
INSERT INTO site_pages (page_name, content_json) VALUES ('faqs', '{"hero":{"title":"Frequently Asked Questions","subtitle":"Everything you need to know about using DineVault."},"items":[{"question":"How do I list my restaurant on DineVault?","answer":"Simply navigate to the Get Listed page and fill out the submission form with your restaurant details. Our team will review your submission and approve it within 24-48 hours. Once approved, your restaurant will appear on the platform for thousands of diners to discover."},{"question":"Is it free to list my restaurant?","answer":"Yes! Listing your restaurant on DineVault is completely free. We believe in making restaurant discovery accessible to everyone, and we do not charge restaurants for basic listings. Premium promotional features may be available in the future."},{"question":"How do reviews work on DineVault?","answer":"Anyone can leave a review for a restaurant they have visited. Reviews include a star rating and a written experience. Restaurant owners can view all reviews through their listing. Our moderation team ensures all reviews are authentic and respectful."},{"question":"Can I edit my restaurant listing after submission?","answer":"Yes. After your listing is approved, you can contact our support team to request edits to your restaurant information, menu, photos, or other details. We are working on a self-service dashboard for restaurant owners in a future update."},{"question":"How do I report an incorrect listing?","answer":"If you notice incorrect information about a restaurant, please use the Contact page to send us the details. Include the restaurant name and what information needs to be corrected. Our team will investigate and update the listing promptly."}],"cta":{"title":"Own a Restaurant?","text":"Join DineVault and reach thousands of food enthusiasts.","btn":{"label":"Get Listed Today","url":"\/restaurant-business\/get-listed.php"}}}');
