INSERT INTO site_pages (page_name, content_json) VALUES ('privacy', '{"hero":{"title":"Privacy Policy"},"content":"At DineVault, we are committed to protecting your privacy. This Privacy Policy explains how we collect, use, disclose, and safeguard your information when you visit our website and use our services.\n\nWe collect personal information such as your name, email address, and dining preferences only when you voluntarily provide it. This information is used to personalize your experience, improve our platform, and communicate with you about restaurant recommendations, updates, and promotions.\n\nWe do not sell, trade, or rent your personal information to third parties. We implement appropriate security measures to protect your personal information from unauthorized access, alteration, disclosure, or destruction.\n\nOur website uses cookies to enhance your browsing experience. You can choose to disable cookies through your browser settings. By using DineVault, you consent to our Privacy Policy."}');
INSERT INTO site_pages (page_name, content_json) VALUES ('terms', '{"hero":{"title":"Terms of Service"},"content":"Welcome to DineVault. By accessing or using our website and services, you agree to be bound by these Terms of Service.\n\nDineVault provides a platform for discovering restaurants, reading reviews, and sharing dining experiences. You may use our services only for lawful purposes and in accordance with these Terms.\n\nYou are responsible for maintaining the confidentiality of your account credentials and for all activities that occur under your account. Reviews submitted to DineVault must be based on genuine personal experiences. Fake, misleading, or defamatory reviews are strictly prohibited.\n\nRestaurant owners are responsible for the accuracy of their listed information. DineVault reserves the right to modify, suspend, or discontinue any part of the service at any time without prior notice. These Terms are governed by the laws of the State of New York."}');
INSERT INTO site_pages (page_name, content_json) VALUES ('disclaimer', '{"hero":{"title":"Disclaimer"},"content":"The information provided on DineVault is for general informational purposes only. While we strive to keep restaurant information accurate and up-to-date, we make no representations or warranties of any kind about the completeness, accuracy, reliability, or availability of the information contained on this platform.\n\nRestaurant listings, menus, pricing, and hours of operation are provided by the restaurants themselves and may change without notice. DineVault does not guarantee the quality of food, service, or dining experience at any listed restaurant.\n\nUser reviews reflect individual opinions and do not represent the views of DineVault. We encourage diners to verify all information directly with the restaurant before visiting. DineVault is not responsible for any loss or damage incurred as a result of relying on information presented on this website."}');
INSERT INTO site_pages (page_name, content_json) VALUES ('listings', '{"hero":{"title":"All Restaurants"},"search_placeholder":"Search restaurants, cuisines, or locations...","filters":{"cuisine_label":"Cuisine","price_label":"Price Range","rating_label":"Rating","clear_btn":"Clear All"},"empty_state":{"icon":"fas fa-search","title":"No restaurants found","text":"Try adjusting your filters or search term."},"results_text":"restaurants found"}');

