INSERT INTO restaurants (status, restaurant_json) VALUES ('approved', '{"name":"La Maison Dor\u00e9e","cuisine":"French","price_range":"$$$$","lat":40.758,"lng":-73.9855,"banner_url":"https:\/\/images.unsplash.com\/photo-1517248135467-4c7edcad34c4?w=1400","about_text":"Nestled in the heart of downtown, La Maison Dor\u00e9e is a beacon of French culinary excellence. With over two decades of history, our kitchen has been led by award-winning Chef Antoine Beaumont, who brings classical French techniques together with locally sourced seasonal ingredients. Every dish tells a story of tradition and innovation, from our signature duck confit to the delicate cr\u00e8me br\u00fbl\u00e9e that has earned us a loyal following. Our wine cellar boasts over 300 carefully curated labels from the finest vineyards in Bordeaux, Burgundy, and the New World.","direct_menu_text":"\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n         LA MAISON DOR\u00c9E \u2014 MENU\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n\u2500\u2500 STARTERS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nFrench Onion Soup Gratin\u00e9e ........... $16\nSeared Foie Gras with Brioche ....... $24\nEscargots de Bourgogne (12 pc) ...... $18\nTuna Tartare with Avocado ........... $22\n\n\u2500\u2500 MAIN COURSES \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nDuck Confit with Lentils ............ $38\nFilet Mignon with Truffle Sauce ...... $52\nPan-Seared Sea Bass .................. $42\nRack of Lamb with Herb Crust ......... $56\n\n\u2500\u2500 DESSERTS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nCr\u00e8me Br\u00fbl\u00e9e ......................... $14\nChocolate Souffl\u00e9 .................... $16\nTarte Tatin .......................... $15\nCheese Selection ..................... $22\n\n\u2500\u2500 WINE HIGHLIGHTS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nCh\u00e2teau Margaux 2018 ................ $185\nOpus One 2019 ........................ $145\nDom P\u00e9rignon Vintage .................. $95","menu_file_path":"","opening_days":"Mon-Sun: 11:30 AM \u2013 10:30 PM","locations":"742 Evergreen Ave, Downtown | 158 Oak Street, Midtown","reviews":[{"name":"Sarah Mitchell","rating":5,"date":"2025-12-15","text":"Absolutely breathtaking dining experience. The duck confit was cooked to perfection and the wine pairing was impeccable. The ambiance transported us straight to Paris."},{"name":"James Rodriguez","rating":5,"date":"2025-11-28","text":"Chef Antoine truly outdid himself. The tasting menu was a journey through flavors I never knew existed. The service was attentive without being intrusive."},{"name":"Emily Chen","rating":4,"date":"2025-10-05","text":"Beautiful restaurant with outstanding food. The cr\u00e8me br\u00fbl\u00e9e is hands down the best I have ever had. Only minor note is the wait time on weekends."}]}');
INSERT INTO restaurants (status, restaurant_json) VALUES ('approved', '{"name":"Sakura Japanese Kitchen","cuisine":"Japanese","price_range":"$$$","lat":40.7282,"lng":-73.7949,"banner_url":"https:\/\/images.unsplash.com\/photo-1579027989536-b7b1f875659b?w=1400","about_text":"Sakura Japanese Kitchen brings the authentic flavors of Tokyo to your neighborhood. Our head chef, Kenji Yamamoto, trained for over fifteen years in some of Tokyo''s most prestigious sushi counters before bringing his artistry abroad. We pride ourselves on sourcing the freshest fish flown in daily from Tsukiji Market, combined with premium Japanese rice and house-made seasonings. From our hand-rolled sushi to our rich tonkotsu ramen, every dish reflects the precision and respect for ingredients that defines true Japanese cuisine.","direct_menu_text":"\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n      SAKURA JAPANESE KITCHEN \u2014 MENU\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n\u2500\u2500 SUSHI & SASHIMI \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nSalmon Nigiri (2 pc) ................. $8\nTuna Sashimi (5 pc) .................. $16\nDragon Roll ......................... $18\nRainbow Roll ....................... $22\nOmakase (Chef''s Choice, 12 pc) ...... $65\n\n\u2500\u2500 RAMEN \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nTonkotsu Ramen ...................... $16\nMiso Ramen .......................... $15\nSpicy Tantanmen ..................... $17\nVeggie Shoyu Ramen ................. $14\n\n\u2500\u2500 SMALL PLATES \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nEdamame .............................. $6\nGyoza (6 pc) ......................... $10\nTempura Platter ..................... $14\nTakoyaki (8 pc) ..................... $12\n\n\u2500\u2500 DRINKS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nSake Flight ......................... $18\nJapanese Whisky Highball ............ $14\nYuzu Soda ........................... $6","menu_file_path":"","opening_days":"Tue-Sun: 12:00 PM \u2013 11:00 PM","locations":"88 Cherry Blossom Lane, East Side","reviews":[{"name":"Mike Tanaka","rating":5,"date":"2026-01-10","text":"The omakase was a revelation. Chef Yamamoto selected the most incredible pieces of fish I have ever tasted. Each piece was a work of art."},{"name":"Lisa Patel","rating":5,"date":"2025-12-20","text":"The tonkotsu ramen is life-changing. Rich, creamy broth with perfectly cooked noodles. A must-visit for any Japanese food lover."},{"name":"David Kim","rating":4,"date":"2025-11-15","text":"Excellent sushi and sashimi. You can really taste the freshness of the fish. Would love to see more dessert options in the future."}]}');
INSERT INTO restaurants (status, restaurant_json) VALUES ('approved', '{"name":"The Copper Grill","cuisine":"American","price_range":"$$$","lat":40.7484,"lng":-73.9857,"banner_url":"https:\/\/images.unsplash.com\/photo-1466978913421-dad2ebd01d17?w=1400","about_text":"The Copper Grill is where rustic charm meets modern American cuisine. Located in a beautifully restored industrial warehouse, our restaurant celebrates bold flavors and honest cooking. Our wood-fired grill is the heart of the kitchen, imparting a smoky depth to everything from our prime steaks to our seasonal vegetables. Chef Maria Santos draws inspiration from her travels across the American heartland, crafting menus that honor regional traditions while pushing culinary boundaries.","direct_menu_text":"\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n        THE COPPER GRILL \u2014 MENU\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n\u2500\u2500 TO START \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nBurrata & Heirloom Tomato ........... $16\nSmoked Wings ......................... $14\nGrilled Corn Chowder ................ $12\nCharred Broccolini .................. $13\n\n\u2500\u2500 FROM THE GRILL \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\n12oz Ribeye Steak ................... $48\nBBQ Brisket (12hr smoked) ........... $36\nGrilled Half Chicken ............... $32\nCedar Plank Salmon .................. $38\nSmoked Pork Ribs .................... $34\n\n\u2500\u2500 SIDES \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nTruffle Mac & Cheese ................. $12\nSmoked Baked Beans ................... $9\nHouse Salad ......................... $10\nCornbread with Honey Butter ......... $8\n\n\u2500\u2500 DESSERTS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n\nBourbon Pecan Pie ................... $14\nSmoked Chocolate Brownie ............ $12\nVanilla Bean Ice Cream .............. $9","menu_file_path":"","opening_days":"Mon-Sun: 11:00 AM \u2013 11:00 PM","locations":"420 Industrial Way, Warehouse District","reviews":[{"name":"Robert Johnson","rating":5,"date":"2026-02-01","text":"The brisket here is the real deal. Smoky, tender, and full of flavor. This place has become our go-to for weekend dinners."},{"name":"Amanda Foster","rating":4,"date":"2025-12-30","text":"Love the atmosphere \u2014 the industrial warehouse conversion is gorgeous. Food is consistently excellent."},{"name":"Chris Martinez","rating":5,"date":"2025-11-20","text":"Best BBQ in the city, hands down. The 12-hour smoked brisket literally melts in your mouth."}]}');
INSERT INTO restaurants (status, restaurant_json) VALUES ('approved', '{"name":"Verde Trattoria","cuisine":"Italian","price_range":"$$$","lat":40.7178,"lng":-73.9988,"banner_url":"https:\/\/images.unsplash.com\/photo-1414235077428-338989a2e8c0?w=1400","about_text":"Verde Trattoria celebrates the vibrant, sun-drenched flavors of Southern Italy. Our open kitchen concept allows guests to witness the art of pasta-making and wood-fired pizza preparation firsthand. Using only imported Italian ingredients - San Marzano tomatoes, 00 flour, fresh mozzarella di bufala, and cold-pressed extra virgin olive oil - we recreate the warmth and authenticity of a Neapolitan trattoria.\r\n\r\nVerde Trattoria celebrates the vibrant, sun-drenched flavors of Southern Italy. Our open kitchen concept allows guests to witness the art of pasta-making and wood-fired pizza preparation firsthand. Using only imported Italian ingredients - San Marzano tomatoes, 00 flour, fresh mozzarella di bufala, and cold-pressed extra virgin olive oil - we recreate the warmth and authenticity of a Neapolitan trattoria.\r\n\r\nVerde Trattoria celebrates the vibrant, sun-drenched flavors of Southern Italy. Our open kitchen concept allows guests to witness the art of pasta-making and wood-fired pizza preparation firsthand. Using only imported Italian ingredients - San Marzano tomatoes, 00 flour, fresh mozzarella di bufala, and cold-pressed extra virgin olive oil - we recreate the warmth and authenticity of a Neapolitan trattoria.","direct_menu_text":"\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\r\n        VERDE TRATTORIA \u2014 MENU\r\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\r\n\r\n\u2500\u2500 ANTIPASTI \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n\r\nBruschetta al Pomodoro ................ $12\r\nCarpaccio di Manzo ................... $18\r\nBurrata Caprese ..................... $16\r\nCalamari Fritti ..................... $15\r\n\r\n\u2500\u2500 PIZZA (Wood-Fired) \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n\r\nMargherita .......................... $18\r\nDiavola (Spicy Salami) .............. $20\r\nQuattro Formaggi ................... $21\r\nProsciutto e Rucola ................ $22\r\n\r\n\u2500\u2500 PASTA \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n\r\nSpaghetti Carbonara ................. $20\r\nPappardelle al Rag\u00f9 ................ $22\r\nLobster Linguine ................... $32\r\nRisotto ai Funghi Porcini .......... $24\r\n\r\n\u2500\u2500 DOLCI \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n\r\nTiramisu ............................ $14\r\nPanna Cotta ........................ $12\r\nCannoli Siciliani ................... $11\r\nAffogato ........................... $9","menu_file_path":"","opening_days":"Mon-Sun: 11:30 AM \u2013 10:00 PM","locations":"15 Olive Garden Blvd, Little Italy | 90 Harbor View, Waterfront","reviews":[{"name":"Rachel Green","rating":5,"date":"2026-01-25","text":"The most authentic Italian food I have had outside of Italy. The pasta is clearly made fresh in-house."},{"name":"Tom Wilson","rating":5,"date":"2025-12-18","text":"I brought my family here and everyone was blown away. The lobster linguine was the highlight."},{"name":"Nina Rossi","rating":4,"date":"2025-10-22","text":"Beautiful atmosphere that transports you to Naples. The open kitchen is such a nice touch."}]}');
INSERT INTO restaurants (status, restaurant_json) VALUES ('approved', '{"name":"Spice Route","cuisine":"Indian","price_range":"$$","lat":40.7359,"lng":-73.9911,"banner_url":"https:\/\/images.unsplash.com\/photo-1514933651103-005eec06c04b?w=1400","about_text":"Spice Route is a culinary journey through the diverse flavors of South Asia and the Middle East. Our chefs have traveled extensively across India, Pakistan, Lebanon, and Morocco to bring you the most authentic recipes passed down through generations. We use traditional spice blends ground fresh daily, combined with modern cooking techniques to create dishes that are both comforting and exciting.","direct_menu_text":"\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\r\n          SPICE ROUTE \u2014 MENU\r\n\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\r\n\r\n\u2500\u2500 MEZZE & STARTERS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n\r\nHummus with Warm Pita ............... $10\r\nFalafel Plate (6 pc) ................ $12\r\nSamosa (Chicken, 3 pc) ............. $9\r\nLamb Kofta Skewers .................. $16\r\n\r\n\u2500\u2500 CURRIES \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n\r\nButter Chicken ...................... $22\r\nLamb Rogan Josh ..................... $26\r\nPalak Paneer ....................... $18\r\nChicken Tikka Masala ................ $20\r\nChana Masala (Vegan) ................ $16\r\n\r\n\u2500\u2500 GRILLS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n\r\nTandoori Chicken .................... $24\r\nSeekh Kebab Platter ................. $28\r\nGrilled Lamb Chops .................. $34\r\n\r\n\u2500\u2500 DESSERTS \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\r\n\r\nGulab Jamun ......................... $8\r\nMango Kulfi ......................... $9\r\nBaklava ............................. $8","menu_file_path":"","locations":"225 Spice Market Road, International District","reviews":[{"name":"Priya Sharma","rating":5,"date":"2026-02-10","text":"As someone who grew up eating authentic Indian food, I can confidently say Spice Route is the real deal."},{"name":"Ahmad Hassan","rating":5,"date":"2025-12-05","text":"The lamb kofta skewers are phenomenal. You can taste the freshness of the spices."},{"name":"Jennifer Park","rating":4,"date":"2025-11-12","text":"Incredible flavors and generous portions. The tandoori chicken was juicy and perfectly spiced."}],"opening_hours":{"monday":"10:00 AM \u2013 8:00 PM","tuesday":"10:00 AM \u2013 8:00 PM","wednesday":"10:00 AM \u2013 8:00 PM","thursday":"10:00 AM \u2013 8:00 PM","friday":"10:00 AM \u2013 8:00 PM","saturday":"10:00 AM \u2013 8:00 PM","sunday":"10:00 AM \u2013 8:00 PM"}}');
